  app.post("/api/webhooks/stripe", async (c) => {
    const signature = c.req.header("stripe-signature") || "";
    const signingSecret = secret.get(stripeWebhookSecretName());
    if (!signingSecret) {
      console.error("[WEBHOOK] signing secret is not configured");
      return c.json({ error: "Webhook not configured" }, 500);
    }
    const stripeKey = getStripeKey();
    if (!stripeKey) {
      console.error("[WEBHOOK] STRIPE_SECRET_KEY not configured");
      return c.json({ error: "Stripe not configured" }, 500);
    }
    const stripe = new stripe_esm_worker_default(stripeKey, { apiVersion: "2023-10-16" });
    const body = await c.req.text();
    let event;
    try {
      event = await stripe.webhooks.constructEventAsync(body, signature, signingSecret);
    } catch {
      console.warn("[WEBHOOK] signature verification failed");
      return c.json({ error: "Invalid Stripe signature" }, 400);
    }
    try {
      console.log(`[WEBHOOK] Received event: ${event.type}`);
      if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
        const session = event.data.object;
        await confirmStripeCheckout(session, "webhook");
      }
      return c.json({ received: true });
    } catch (err) {
      console.error("[WEBHOOK] processing error:", err);
      return c.json({ error: `Webhook processing failed: ${err.message}` }, 500);
    }
  });
